"use client";

import { useMutation, usePaginatedQuery, useQuery } from "convex/react";
import { ConvexError } from "convex/values";
import { useEffect, useState, type FormEvent } from "react";
import { api } from "@/convex/_generated/api";
import type { Id } from "@/convex/_generated/dataModel";
import { Card } from "@/components/AppShell";
import { formatBusinessDay } from "@/lib/format";
import { PartnerDistributions } from "@/components/workspace/PartnerDistributions";

type Account = "cash" | "mobile_money";
type FinanceAccount = "all" | "cash" | "mobile_money" | "unallocated";
type Screen = "Movements" | "Savings" | "Loans" | "Partners" | "Bills" | "Reconcile";

function accountName(account: Account) { return account === "cash" ? "Cash" : "Mobile money"; }
function businessDate(timezone: string) {
  return new Intl.DateTimeFormat("en-CA", { timeZone: timezone, year: "numeric", month: "2-digit", day: "2-digit" }).format(new Date());
}
function thursdayDates(startOn: string, latestOn: string) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(startOn) || !/^\d{4}-\d{2}-\d{2}$/.test(latestOn) || startOn > latestOn) return [];
  const first = new Date(`${startOn}T00:00:00.000Z`);
  const latest = new Date(`${latestOn}T00:00:00.000Z`);
  first.setUTCDate(first.getUTCDate() + ((4 - first.getUTCDay() + 7) % 7));
  const dates: string[] = [];
  for (const date = new Date(first); date <= latest && dates.length <= 520; date.setUTCDate(date.getUTCDate() + 7)) dates.push(date.toISOString().slice(0, 10));
  return dates;
}

export function OperationsWorkspace({ screen, currency, scale, locale, timezone, dateFormat, range, account, recordFormOpen, onRecordSaved }: { screen: Screen; currency: string; scale: number; locale: string; timezone: string; dateFormat: "DD/MM/YYYY" | "MM/DD/YYYY" | "YYYY-MM-DD"; range: { from: string; toExclusive: string }; account: FinanceAccount; recordFormOpen: boolean; onRecordSaved: () => void }) {
  const access = useQuery(api.workspace.currentAccess, {});
  const data = useQuery(api.operations.overview, access?.access === "ready" ? { businessId: access.businessId, ...range, ...(account === "all" ? {} : { account }) } : "skip");
  const canSeeArchived = data?.access === "ready" && (data.role === "owner" || data.role === "cashier");
  const savingsArchive = usePaginatedQuery(api.operations.savingsArchive, screen === "Savings" && canSeeArchived && data?.access === "ready" ? { businessId: data.businessId } : "skip", { initialNumItems: 20 });
  const billArchive = usePaginatedQuery(api.operations.billArchive, screen === "Bills" && canSeeArchived && data?.access === "ready" ? { businessId: data.businessId } : "skip", { initialNumItems: 20 });
  const partnerArchive = usePaginatedQuery(api.operations.partnerArchive, screen === "Partners" && data?.access === "ready" && data.role === "owner" ? { businessId: data.businessId } : "skip", { initialNumItems: 20 });
  const distributionAccess = useQuery(api.distributions.overview, screen === "Partners" && access?.access === "ready" ? { businessId: access.businessId, paginationOpts: { numItems: 20, cursor: null } } : "skip");
  const partnerStatement = useQuery(api.operations.partnerStatement, screen === "Partners" && access?.access === "ready" ? { businessId: access.businessId, ...range, ...(account === "all" ? {} : { account }) } : "skip");
  const createMovement = useMutation(api.operations.createMovement);
  const reverseMovement = useMutation(api.operations.reverseMovement);
  const createSavingsHolding = useMutation(api.operations.createSavingsHolding);
  const updateSavingsHolding = useMutation(api.operations.updateSavingsHolding);
  const recordSavingsFlow = useMutation(api.operations.recordSavingsFlow);
  const recordWeeklySavingsContributions = useMutation(api.operations.recordWeeklySavingsContributions);
  const reverseSavingsFlow = useMutation(api.operations.reverseSavingsFlow);
  const createLoan = useMutation(api.operations.createLoan);
  const recordLoanRepayment = useMutation(api.operations.recordLoanRepayment);
  const reverseLoanRepayment = useMutation(api.operations.reverseLoanRepayment);
  const createBill = useMutation(api.operations.createBill);
  const updateBillSchedule = useMutation(api.operations.updateBillSchedule);
  const recordBillPayment = useMutation(api.operations.recordBillPayment);
  const reverseBillPayment = useMutation(api.operations.reverseBillPayment);
  const createReconciliation = useMutation(api.operations.createReconciliation);
  const supersedeReconciliation = useMutation(api.operations.supersedeReconciliation);
  const explainReconciliation = useMutation(api.operations.explainReconciliation);
  const reopenReconciliation = useMutation(api.operations.reopenReconciliation);
  const createPartner = useMutation(api.operations.createPartner);
  const updatePartnerProfile = useMutation(api.operations.updatePartnerProfile);
  const updatePartnerStatus = useMutation(api.operations.updatePartnerStatus);
  const [keys, setKeys] = useState<Record<string, string>>({});
  const [busy, setBusy] = useState(false);
  const [feedback, setFeedback] = useState<{ error: boolean; message: string } | null>(null);
  const [warning, setWarning] = useState<{ message: string; retry: () => Promise<void> } | null>(null);
  const [billCategory, setBillCategory] = useState("Bandwidth");
  const [day, setDay] = useState(() => businessDate(timezone));
  const [weeklyStartOn, setWeeklyStartOn] = useState(() => businessDate(timezone));
  const [weeklyLatestOn, setWeeklyLatestOn] = useState(() => businessDate(timezone));
  const [weeklyAmount, setWeeklyAmount] = useState("");
  const weeklyDates = thursdayDates(weeklyStartOn, weeklyLatestOn);
  const fmt = (amount: number) => new Intl.NumberFormat(locale, { style: "currency", currency, maximumFractionDigits: Math.log10(scale) }).format(amount / scale);
  useEffect(() => {
    const refreshDay = () => setDay(businessDate(timezone));
    refreshDay();
    const timer = window.setInterval(refreshDay, 60_000);
    window.addEventListener("focus", refreshDay);
    return () => { window.clearInterval(timer); window.removeEventListener("focus", refreshDay); };
  }, [timezone]);
  function billDueLabel(dueOn: string) {
    const remaining = Math.round((Date.parse(`${dueOn}T00:00:00.000Z`) - Date.parse(`${day}T00:00:00.000Z`)) / 86_400_000);
    return remaining < 0 ? `Overdue by ${Math.abs(remaining)} ${Math.abs(remaining) === 1 ? "day" : "days"}` : remaining === 0 ? "Due today" : `${remaining} ${remaining === 1 ? "day" : "days"} left`;
  }
  function selectedBusinessId() {
    if (data?.access !== "ready") throw new Error("Workspace is still loading.");
    return data.businessId;
  }

  function form(scope: string, action: (values: FormData, key: string, confirmNegative: boolean) => Promise<unknown>) {
    return (event: FormEvent<HTMLFormElement>) => {
      event.preventDefault();
      const element = event.currentTarget;
      const values = new FormData(element);
      const key = keys[scope] ?? crypto.randomUUID();
      setKeys(current => ({ ...current, [scope]: key }));
      const run = async (currentValues: FormData, confirmNegative: boolean) => {
        setBusy(true); setFeedback(null); setWarning(null);
        try {
          const result = await action(currentValues, key, confirmNegative);
          setKeys(current => { const next = { ...current }; delete next[scope]; return next; });
          element.reset();
          if (scope === "savings-weekly") { setWeeklyAmount(""); setWeeklyStartOn(day); setWeeklyLatestOn(day); }
          setFeedback({ error: false, message: scope === "savings-weekly" && Array.isArray(result) ? `Recorded ${result.length} weekly contribution${result.length === 1 ? "" : "s"}. Each date is listed separately in savings activity.` : "Saved. The cashbook and audit trail have been updated." });
          if (["movement", "holding", "savings-flow", "savings-weekly", "loan", "loan-repayment", "bill", "bill-payment", "reconcile", "partner"].includes(scope)) onRecordSaved();
        } catch (error) {
          const details = error instanceof ConvexError ? error.data as { code?: string; message?: string } : null;
          if (details?.code === "CONFIRM_NEGATIVE" && !confirmNegative) {
            setWarning({ message: details.message ?? "This transaction may create a negative balance.", retry: async () => { if (element.reportValidity()) await run(new FormData(element), true); } });
          } else setFeedback({ error: true, message: error instanceof Error ? error.message : "Could not save this record." });
        } finally { setBusy(false); }
      };
      void run(values, false);
    };
  }

  async function reverseMovementWithReview(movementId: Id<"movements">, reason: string, confirmNegative = false) {
    setBusy(true); setFeedback(null);
    try {
      await reverseMovement({ businessId: selectedBusinessId(), movementId, reason, confirmNegativeBalance: confirmNegative });
      setFeedback({ error: false, message: "Movement reversed; account balances and linked history were updated." });
    } catch (error) {
      const details = error instanceof ConvexError ? error.data as { code?: string; message?: string } : null;
      if (details?.code === "CONFIRM_NEGATIVE" && !confirmNegative && window.confirm(`${details.message ?? "This reversal may create a negative balance."} Continue with the reversal?`)) {
        await reverseMovementWithReview(movementId, reason, true);
      } else {
        setFeedback({ error: true, message: details?.message ?? (error instanceof Error ? error.message : "Could not reverse movement.") });
      }
    } finally { setBusy(false); }
  }

  async function reverseWithReview(run: (confirmNegative: boolean) => Promise<unknown>, successMessage: string, confirmNegative = false) {
    setBusy(true); setFeedback(null);
    try {
      await run(confirmNegative);
      setFeedback({ error: false, message: successMessage });
    } catch (error) {
      const details = error instanceof ConvexError ? error.data as { code?: string; message?: string } : null;
      if (details?.code === "CONFIRM_NEGATIVE" && !confirmNegative && window.confirm(`${details.message ?? "This reversal may create a negative balance."} Continue with the reversal?`)) {
        await reverseWithReview(run, successMessage, true);
      } else {
        setFeedback({ error: true, message: details?.message ?? (error instanceof Error ? error.message : "Could not reverse this record.") });
      }
    } finally { setBusy(false); }
  }

  async function saveLifecycleChange(run: () => Promise<unknown>, successMessage: string) {
    setBusy(true); setFeedback(null);
    try {
      await run();
      setFeedback({ error: false, message: successMessage });
    } catch (error) {
      setFeedback({ error: true, message: error instanceof Error ? error.message : "Could not update this record." });
    } finally { setBusy(false); }
  }

  if (!data) return <div className="empty-state" role="status"><strong>Loading workspace records…</strong><span>These views use live, authorized Convex data.</span></div>;
  if (data.access === "pending") return <div className="notice-banner notice-warning" role="status">Workspace access is pending. Ask an owner to invite this account.</div>;
  if (data.access === "restricted" && screen === "Partners" && distributionAccess?.access === "ready" && distributionAccess.canApproveDistributions) return <PartnerDistributions range={range} currency={currency} scale={scale} locale={locale} dateFormat={dateFormat} partners={[]} today={businessDate(timezone)} />;
  if (data.access === "restricted" && screen === "Partners") {
    if (!partnerStatement) return <div className="empty-state" role="status"><strong>Loading partner statement…</strong><span>Only your linked partner account can read this statement.</span></div>;
    if (partnerStatement.access !== "ready") return <div className="notice-banner notice-info" role="status">This partner login is not linked to an active partner record. Ask the workspace owner to link it in Settings → Access.</div>;
    const partnerDigits = partnerStatement.currencyMinorDigits ?? 0;
    const partnerScale = 10 ** partnerDigits;
    const partnerFmt = (amount: number) => new Intl.NumberFormat(partnerStatement.locale, { style: "currency", currency: partnerStatement.currency, maximumFractionDigits: partnerDigits }).format(amount / partnerScale);
    return <div className="board-grid board-grid-operations">
      <Card className="board-feature-card"><div className="card-heading"><div><h2 className="card-title">Your partner statement</h2><p className="card-subtitle">This view contains only the partner record linked to your sign-in.</p></div></div><div className="settings-facts"><div><span>Partner</span><strong>{partnerStatement.partner}</strong></div><div><span>Ownership</span><strong>{(partnerStatement.ownershipBps / 100).toFixed(2)}%</strong></div><div><span>Attributed capital contributions</span><strong>{partnerStatement.capitalTotalComplete ? partnerFmt(partnerStatement.capitalContributedUgx) : `At least ${partnerFmt(partnerStatement.capitalContributedUgx)}`}</strong></div></div>{!partnerStatement.capitalTotalComplete && <p className="notice-banner notice-warning">This partner has more than 5,000 historical movements. The displayed capital total is incomplete and needs owner reconciliation.</p>}<p className="muted-note">Approved allocation is a snapshot, not a promise of cash. Payouts appear only after the owner records payment.</p></Card>
      <Card className="board-section-card"><div className="card-heading"><div><h2 className="card-title">Your capital contribution history</h2><p className="card-subtitle">Attributed capital recorded in the selected period.</p></div></div>{partnerStatement.contributions.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>Date</th><th>Received by</th><th>Amount</th><th>Description</th></tr></thead><tbody>{partnerStatement.contributions.map(row => <tr key={row._id}><td>{formatBusinessDay(row.occurredOn, partnerStatement.dateFormat)}</td><td>{accountName(row.account)}</td><td>{partnerFmt(row.amountUgx)}</td><td>{row.note || "—"}</td></tr>)}</tbody></table></div> : <Empty message="No capital contributions recorded in this period." detail="Choose a wider period or ask the owner whether a contribution has been recorded." />}</Card>
      <Card className="board-section-card"><div className="card-heading"><div><h2 className="card-title">Your distributions and payout history</h2><p className="card-subtitle">Approved allocations follow the profit period; payments follow the date they were actually recorded.</p></div></div>{partnerStatement.distributions.length ? partnerStatement.distributions.map(row => <div className="distribution-history" key={row.id}><div className="health-row"><strong>{formatBusinessDay(row.periodFrom, partnerStatement.dateFormat)} · {row.status.replaceAll("_", " ")}</strong><span>Allocated {partnerFmt(row.allocatedUgx)} · paid {partnerFmt(row.paidUgx)} · unpaid {partnerFmt(row.unpaidUgx)}</span></div></div>) : <Empty message="No distribution allocations in this period." detail="Pending requests are not shown as entitlement. Approved allocations appear after independent review." />}{!partnerStatement.distributionsComplete && <p className="notice-banner notice-warning">This statement has more than 500 distribution records. Ask the owner for a wider audit export.</p>}<h3 className="card-title">Payments recorded in this period</h3>{partnerStatement.payouts.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>Paid on</th><th>Profit period</th><th>Account</th><th>Amount</th><th>Status</th></tr></thead><tbody>{partnerStatement.payouts.map(payout => <tr key={payout.id}><td>{formatBusinessDay(payout.paidOn, partnerStatement.dateFormat)}</td><td>{formatBusinessDay(payout.periodFrom, partnerStatement.dateFormat)}</td><td>{accountName(payout.account)}</td><td>{partnerFmt(payout.amountUgx)}</td><td>{payout.state === "posted" ? "Paid" : `Reversed${payout.reversalReason ? ` · ${payout.reversalReason}` : ""}`}</td></tr>)}</tbody></table></div> : <Empty message="No payouts recorded in this period." detail="Payments appear here based on their payment date, even when the profit period is older." />}{!partnerStatement.payoutsComplete && <p className="notice-banner notice-warning">More than 500 payout records fall in this period. This list is capped and incomplete; ask the owner for an audit export.</p>}</Card>
    </div>;
  }
  if (data.access === "restricted") return <div className="notice-banner notice-info" role="status">This financial workflow is restricted to owners and cashiers. Use the Partners page for your linked partner statement.</div>;
  const records = data;
  const today = businessDate(timezone);
  const canCreateLoans = access?.access === "ready" && access.permissions.includes("loans.create");
  const canRepayLoans = access?.access === "ready" && access.permissions.includes("loans.repay");
  const canCreateBills = access?.access === "ready" && access.permissions.includes("bills.create");
  const canPayBills = access?.access === "ready" && access.permissions.includes("bills.pay");
  const periodNote = <p className="muted-note">The selected period filters transaction history. Account filtering applies to account-linked activity; holdings and partner ownership have no account field. Current balances and schedules show their latest status.</p>;
  const sharedMessages = <>
    {warning && <div className="notice-banner notice-warning" role="alert"><strong>Balance warning</strong><p>{warning.message}</p><button className="button button-accent" type="button" disabled={busy} onClick={() => void warning.retry()}>Review and continue</button></div>}
    {feedback && <p className={`form-feedback ${feedback.error ? "form-error" : "form-success"}`} role="status">{feedback.message}</p>}
  </>;
  const rowActions = <p className="muted-note">Amounts use {currency} precision. Every saved action is audit logged; saved records are not silently removed.</p>;

  if (screen === "Movements") return <div className="board-grid board-grid-operations">{periodNote}{sharedMessages}
    <div id="record-entry-card" hidden={!recordFormOpen}><Card className="board-feature-card"><div className="card-heading"><div><h2 className="card-title">Record a movement</h2><p className="card-subtitle">Transfers affect account balances only. Contributions are not sales income. Withdrawal fees are recorded as expenses.</p></div></div>
      <form className="form-layout" onSubmit={form("movement", async (v, key, confirmNegative) => createMovement({ businessId: selectedBusinessId(), kind: String(v.get("kind")) as "transfer" | "withdrawal" | "deposit" | "capital_contribution", amountUgx: Math.round(Number(v.get("amount")) * scale), feeUgx: v.get("fee") ? Math.round(Number(v.get("fee")) * scale) : undefined, fromAccount: String(v.get("fromAccount")) as Account, toAccount: String(v.get("toAccount")) as Account, partnerId: v.get("partnerId") ? String(v.get("partnerId")) as Id<"partners"> : undefined, occurredOn: String(v.get("occurredOn")), note: String(v.get("note") ?? "").trim(), idempotencyKey: key, confirmNegativeBalance: confirmNegative }))}>
        <div className="field"><label htmlFor="move-kind">Movement type</label><select id="move-kind" name="kind"><option value="transfer">Account transfer</option><option value="withdrawal">Mobile money withdrawal</option><option value="deposit">External deposit</option><option value="capital_contribution">Partner capital contribution</option></select></div>
        <div className="field"><label htmlFor="move-amount">Amount ({currency})</label><input id="move-amount" name="amount" type="number" min={1 / scale} step={1 / scale} required /></div>
        <div className="field"><label htmlFor="move-from">From account</label><select id="move-from" name="fromAccount"><option value="mobile_money">Mobile money</option><option value="cash">Cash</option></select></div>
        <div className="field"><label htmlFor="move-to">To account</label><select id="move-to" name="toAccount"><option value="cash">Cash</option><option value="mobile_money">Mobile money</option></select></div>
        <div className="field"><label htmlFor="move-fee">Withdrawal fee ({currency})</label><input id="move-fee" name="fee" type="number" min="0" step={1 / scale} defaultValue="0" /></div>
        <div className="field"><label htmlFor="move-partner">Partner for capital</label><select id="move-partner" name="partnerId"><option value="">Choose if applicable</option>{records.partners.map(p => <option key={p._id} value={p._id}>{p.name}</option>)}</select></div>
        <div className="field"><label htmlFor="move-date">Date</label><input id="move-date" name="occurredOn" type="date" defaultValue={day} required /></div>
        <div className="field"><label htmlFor="move-note">Description</label><input id="move-note" name="note" maxLength={300} /></div>
        <div className="form-actions"><button className="button button-accent" disabled={busy}>{busy ? "Saving…" : "Save movement"}</button></div>
      </form>{rowActions}</Card></div>
    <Card className="board-section-card"><div className="card-heading"><div><h2 className="card-title">Movement ledger</h2><p className="card-subtitle">Latest 100 saved movements. Transfers and capital are excluded from sales and expenses.</p></div></div>
      {records.movements.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>Date</th><th>Type</th><th>From → To</th><th>Amount</th><th>Note</th><th>Status</th><th>Action</th></tr></thead><tbody>{records.movements.map(row => <tr key={row._id}><td>{formatBusinessDay(row.occurredOn, dateFormat)}</td><td>{row.kind.replaceAll("_", " ")}{row.feeUgx ? ` · fee ${fmt(row.feeUgx)}` : ""}</td><td>{row.fromAccount ? accountName(row.fromAccount) : "External"} → {row.toAccount ? accountName(row.toAccount) : "External"}</td><td>{fmt(row.amountUgx)}</td><td>{row.partnerName ? `${row.partnerName}: ` : ""}{row.note || "—"}</td><td>{row.state === "void" ? `Reversed · ${row.voidReason ?? ""}` : "Posted"}</td><td>{records.role === "owner" && row.state === "posted" ? <button className="button" type="button" disabled={busy} onClick={() => { const reason = window.prompt("Reason for reversing this movement (at least 5 characters):") ?? ""; if (reason.trim().length >= 5) void reverseMovementWithReview(row._id, reason); }}>Reverse…</button> : "—"}</td></tr>)}</tbody></table></div> : <Empty message="No movements recorded yet." detail="Transfers, deposits, withdrawals, and partner contributions appear here." />}
    </Card>
  </div>;

  if (screen === "Savings") return <div className="board-grid board-grid-operations">{periodNote}{sharedMessages}
    <div id="record-entry-card" hidden={!recordFormOpen}><Card className="board-feature-card"><h2 className="card-title">Create a savings holding</h2><p className="card-subtitle">Contributions move money out of a business account into a tracked reserve. They are not expenses.</p><form className="form-layout" onSubmit={form("holding", async (v, key) => createSavingsHolding({ businessId: selectedBusinessId(), name: String(v.get("name")), targetUgx: v.get("target") ? Math.round(Number(v.get("target")) * scale) : undefined, idempotencyKey: key }))}><div className="field"><label htmlFor="saving-name">Holding name</label><input id="saving-name" name="name" minLength={2} maxLength={80} required /></div><div className="field"><label htmlFor="saving-target">Target ({currency}, optional)</label><input id="saving-target" name="target" type="number" min={1 / scale} step={1 / scale} /></div><div className="form-actions"><button className="button button-accent" disabled={busy}>Create holding</button></div></form>
      {records.savings.length > 0 && <><h3 className="card-title">Record a contribution or withdrawal</h3><form className="form-layout" onSubmit={form("savings-flow", async (v, key, confirmNegative) => recordSavingsFlow({ businessId: selectedBusinessId(), holdingId: String(v.get("holdingId")) as Id<"savingsHoldings">, kind: String(v.get("kind")) as "contribution" | "withdrawal", amountUgx: Math.round(Number(v.get("amount")) * scale), account: String(v.get("account")) as Account, occurredOn: String(v.get("occurredOn")), note: String(v.get("note") ?? ""), idempotencyKey: key, confirmNegativeBalance: confirmNegative }))}><div className="field"><label htmlFor="saving-holding">Holding</label><select id="saving-holding" name="holdingId">{records.savings.map(item => <option key={item._id} value={item._id}>{item.name}</option>)}</select></div><div className="field"><label htmlFor="saving-kind">Action</label><select id="saving-kind" name="kind"><option value="contribution">Contribute</option><option value="withdrawal">Withdraw</option></select></div><div className="field"><label htmlFor="saving-amount">Amount ({currency})</label><input id="saving-amount" name="amount" type="number" min={1 / scale} step={1 / scale} required /></div><div className="field"><label htmlFor="saving-account">Business account</label><select id="saving-account" name="account"><option value="cash">Cash</option><option value="mobile_money">Mobile money</option></select></div><div className="field"><label htmlFor="saving-date">Date</label><input id="saving-date" name="occurredOn" type="date" defaultValue={day} required /></div><div className="field"><label htmlFor="saving-note">Description</label><input id="saving-note" name="note" maxLength={300} /></div><div className="form-actions"><button className="button button-accent" disabled={busy}>Save savings action</button></div></form></>}
      {records.savings.length > 0 && <><h3 className="card-title">Record weekly Thursday contributions</h3><p className="card-subtitle">Choose a date range and one contribution amount. The app records one separate contribution on each Thursday from the start date through the latest date. Future dates are not posted.</p><form className="form-layout" onSubmit={form("savings-weekly", async (v, key, confirmNegative) => recordWeeklySavingsContributions({ businessId: selectedBusinessId(), holdingId: String(v.get("holdingId")) as Id<"savingsHoldings">, amountUgx: Math.round(Number(v.get("amount")) * scale), account: String(v.get("account")) as Account, startOn: String(v.get("startOn")), latestOn: String(v.get("latestOn")), note: String(v.get("note") ?? ""), idempotencyKey: key, confirmNegativeBalance: confirmNegative }))}><div className="field"><label htmlFor="weekly-saving-holding">Holding</label><select id="weekly-saving-holding" name="holdingId">{records.savings.map(item => <option key={item._id} value={item._id}>{item.name}</option>)}</select></div><div className="field"><label htmlFor="weekly-saving-amount">Amount each Thursday ({currency})</label><input id="weekly-saving-amount" name="amount" type="number" min={1 / scale} step={1 / scale} value={weeklyAmount} onChange={event => setWeeklyAmount(event.target.value)} required /></div><div className="field"><label htmlFor="weekly-saving-account">Contribute from</label><select id="weekly-saving-account" name="account"><option value="cash">Cash</option><option value="mobile_money">Mobile money</option></select></div><div className="field"><label htmlFor="weekly-saving-start">Start date</label><input id="weekly-saving-start" name="startOn" type="date" value={weeklyStartOn} onChange={event => setWeeklyStartOn(event.target.value)} max={day} required /></div><div className="field"><label htmlFor="weekly-saving-latest">Latest date (inclusive)</label><input id="weekly-saving-latest" name="latestOn" type="date" value={weeklyLatestOn} onChange={event => setWeeklyLatestOn(event.target.value)} min={weeklyStartOn} max={day} required /></div><div className="field"><label htmlFor="weekly-saving-note">Description (optional)</label><input id="weekly-saving-note" name="note" maxLength={300} placeholder="Weekly Thursday contribution" /></div><p className="muted-note field-full">{weeklyDates.length === 0 ? "No Thursday falls in this date range. Extend the latest date to include a Thursday." : weeklyDates.length > 520 ? "This range exceeds the 520-week limit. Shorten it to 10 years or less." : `${weeklyDates.length} separate contribution${weeklyDates.length === 1 ? "" : "s"}${weeklyAmount && Number.isFinite(Number(weeklyAmount)) ? ` · total ${fmt(Math.round(Number(weeklyAmount) * scale) * weeklyDates.length)}` : ""}. First: ${weeklyDates[0]}; last: ${weeklyDates[weeklyDates.length - 1]}.`}</p><div className="form-actions"><button className="button button-accent" disabled={busy || weeklyDates.length === 0 || weeklyDates.length > 520}>Record weekly contributions</button></div></form></>}
    </Card></div>
    <Card className="board-section-card"><h2 className="card-title">Recorded reserve balances</h2>{records.savings.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>Holding</th><th>Recorded balance</th><th>Target</th><th>Progress</th><th>Actions</th></tr></thead><tbody>{records.savings.map(row => <tr key={row._id}><td>{row.name}</td><td>{fmt(row.balanceUgx)}</td><td>{row.targetUgx === undefined ? "—" : fmt(row.targetUgx)}</td><td>{row.targetUgx ? `${Math.min(100, Math.round(row.balanceUgx / row.targetUgx * 100))}%` : "No target"}</td><td>{records.role === "owner" ? <><button className="button" type="button" disabled={busy} onClick={() => { const name = window.prompt("Holding name:", row.name); if (name === null) return; const target = window.prompt(`Target in ${currency} (leave blank for none):`, row.targetUgx === undefined ? "" : String(row.targetUgx / scale)); if (target === null) return; const targetUgx = target.trim() ? Math.round(Number(target) * scale) : undefined; void saveLifecycleChange(() => updateSavingsHolding({ businessId: selectedBusinessId(), holdingId: row._id, action: "edit", expectedActive: true, name, targetUgx }), "Savings holding updated."); }}>Edit</button> <button className="button" type="button" disabled={busy || row.balanceUgx !== 0} title={row.balanceUgx !== 0 ? "Withdraw the remaining balance before archiving." : undefined} onClick={() => { if (window.confirm(`Archive ${row.name}? Its history will remain available.`)) void saveLifecycleChange(() => updateSavingsHolding({ businessId: selectedBusinessId(), holdingId: row._id, action: "archive", expectedActive: true, name: row.name, targetUgx: row.targetUgx }), "Savings holding archived."); }}>Archive</button></> : "—"}</td></tr>)}</tbody></table></div> : <Empty message="No holdings recorded." detail="Use Record in the page action bar to create a holding, then record contributions and withdrawals against it." />}{savingsArchive.results.length > 0 && <details className="record-archive"><summary>Archived holdings ({savingsArchive.results.length})</summary><div className="table-scroll"><table className="data-table"><thead><tr><th>Holding</th><th>Balance</th><th>Target</th><th>Action</th></tr></thead><tbody>{savingsArchive.results.map(row => <tr key={row._id}><td>{row.name}</td><td>{fmt(row.balanceUgx)}</td><td>{row.targetUgx === undefined ? "—" : fmt(row.targetUgx)}</td><td>{records.role === "owner" ? <button className="button" type="button" disabled={busy} onClick={() => void saveLifecycleChange(() => updateSavingsHolding({ businessId: selectedBusinessId(), holdingId: row._id, action: "restore", expectedActive: false, name: row.name, targetUgx: row.targetUgx }), "Savings holding restored.")}>Restore</button> : "—"}</td></tr>)}</tbody></table>{savingsArchive.status === "CanLoadMore" && <button className="button" type="button" onClick={() => savingsArchive.loadMore(20)}>Load older archived holdings</button>}</div></details>}<h3 className="card-title">Recent savings activity</h3><p className="card-subtitle">One row per contribution or withdrawal. The page’s period and account filters determine which dates appear; choose Custom to view a longer backfill.</p>{records.savingsFlows.length > 0 ? <div className="table-scroll"><table className="data-table"><thead><tr><th>Date</th><th>Holding</th><th>Action</th><th>Amount</th><th>Business account</th><th>Status</th><th>Action</th></tr></thead><tbody>{records.savingsFlows.map(row => <tr key={row._id}><td>{formatBusinessDay(row.occurredOn, dateFormat)}</td><td>{row.holdingName}</td><td>{row.kind}</td><td>{fmt(row.amountUgx)}</td><td>{accountName(row.account)}</td><td>{row.state === "void" ? `Reversed · ${row.voidReason ?? ""}` : row.canReverse ? "Posted" : "Posted · restore holding to reverse"}</td><td>{records.role === "owner" && row.state === "posted" && row.canReverse ? <button className="button" type="button" disabled={busy} onClick={() => { const reason = window.prompt("Reason for reversing this savings activity (at least 5 characters):") ?? ""; if (reason.trim().length >= 5) void reverseWithReview(confirmed => reverseSavingsFlow({ businessId: selectedBusinessId(), flowId: row._id, reason, confirmNegativeBalance: confirmed }), "Savings activity reversed; holding and account balances were updated."); }}>Reverse…</button> : "—"}</td></tr>)}</tbody></table></div> : <Empty message="No savings activity in this range." detail="Try a wider custom date range or a different account filter. Bulk weekly contributions appear as one row per Thursday." />}{rowActions}</Card>
  </div>;

  if (screen === "Loans") return <div className="board-grid board-grid-operations">{periodNote}{sharedMessages}
    <div id="record-entry-card" hidden={!recordFormOpen}><Card className="board-feature-card">
      {canCreateLoans && <><h2 className="card-title">Register a loan</h2><p className="card-subtitle">Disbursement increases the chosen account and creates a liability. It is not sales income.</p><form className="form-layout" onSubmit={form("loan", async (v, key) => createLoan({ businessId: selectedBusinessId(), lender: String(v.get("lender")), principalUgx: Math.round(Number(v.get("principal")) * scale), annualRateBps: Math.round(Number(v.get("rate")) * 100), termMonths: Number(v.get("term")), startedOn: String(v.get("startedOn")), account: String(v.get("account")) as Account, note: String(v.get("note") ?? ""), idempotencyKey: key }))}><div className="field"><label htmlFor="loan-lender">Lender</label><input id="loan-lender" name="lender" minLength={2} maxLength={100} required /></div><div className="field"><label htmlFor="loan-principal">Principal ({currency})</label><input id="loan-principal" name="principal" type="number" min={1 / scale} step={1 / scale} required /></div><div className="field"><label htmlFor="loan-rate">Annual rate (%)</label><input id="loan-rate" name="rate" type="number" min="0" max="10000" step="0.01" defaultValue="0" required /></div><div className="field"><label htmlFor="loan-term">Term (months)</label><input id="loan-term" name="term" type="number" min="1" max="600" defaultValue="12" required /></div><div className="field"><label htmlFor="loan-start">Start date</label><input id="loan-start" name="startedOn" type="date" defaultValue={day} required /></div><div className="field"><label htmlFor="loan-account">Deposit account</label><select id="loan-account" name="account"><option value="cash">Cash</option><option value="mobile_money">Mobile money</option></select></div><div className="field field-full"><label htmlFor="loan-note">Description</label><input id="loan-note" name="note" maxLength={300} /></div><div className="form-actions"><button className="button button-accent" disabled={busy}>Save loan</button></div></form></>}
      {canRepayLoans && records.loans.some(row => row.status === "active") && <><h3 className="card-title">Record a repayment</h3><p className="card-subtitle">Separate principal from interest. Only interest is counted as an expense; enter zero principal for an interest-only payment.</p><form className="form-layout" onSubmit={form("loan-repayment", async (v, key, confirmNegative) => recordLoanRepayment({ businessId: selectedBusinessId(), loanId: String(v.get("loanId")) as Id<"loans">, principalUgx: Math.round(Number(v.get("principal")) * scale), interestUgx: Math.round(Number(v.get("interest")) * scale), paidOn: String(v.get("paidOn")), account: String(v.get("account")) as Account, idempotencyKey: key, confirmNegativeBalance: confirmNegative }))}><div className="field"><label htmlFor="repay-loan">Loan</label><select id="repay-loan" name="loanId">{records.loans.filter(row => row.status === "active").map(row => <option key={row._id} value={row._id}>{row.lender} · outstanding {fmt(row.outstandingPrincipalUgx)}</option>)}</select></div><div className="field"><label htmlFor="repay-principal">Principal paid ({currency})</label><input id="repay-principal" name="principal" type="number" min="0" step={1 / scale} defaultValue="0" required /></div><div className="field"><label htmlFor="repay-interest">Interest paid ({currency})</label><input id="repay-interest" name="interest" type="number" min="0" step={1 / scale} defaultValue="0" required /></div><div className="field"><label htmlFor="repay-account">Paid from</label><select id="repay-account" name="account"><option value="cash">Cash</option><option value="mobile_money">Mobile money</option></select></div><div className="field"><label htmlFor="repay-date">Paid on</label><input id="repay-date" name="paidOn" type="date" defaultValue={day} required /></div><div className="form-actions"><button className="button button-accent" disabled={busy}>Save repayment</button></div></form></>}
    </Card></div>
    <Card className="board-section-card"><h2 className="card-title">Loans and outstanding principal</h2>{records.loans.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>Lender</th><th>Principal</th><th>Rate</th><th>Term</th><th>Est. monthly payment</th><th>Outstanding</th><th>Status</th></tr></thead><tbody>{records.loans.map(row => { const monthlyRate = row.annualRateBps / 10_000 / 12; const estimatedPayment = monthlyRate === 0 ? row.principalUgx / row.termMonths : row.principalUgx * monthlyRate / (1 - Math.pow(1 + monthlyRate, -row.termMonths)); return <tr key={row._id}><td>{row.lender}</td><td>{fmt(row.principalUgx)}</td><td>{(row.annualRateBps / 100).toFixed(2)}%</td><td>{row.termMonths} months</td><td>{fmt(Math.round(estimatedPayment))}<div className="muted-note">illustrative fixed-rate estimate</div></td><td>{fmt(row.outstandingPrincipalUgx)}</td><td>{row.status.replace("_", " ")}</td></tr>; })}</tbody></table></div> : <Empty message="No loans recorded." detail="Register an actual loan above. Planner examples are not saved as financial records." />}{records.loanRepayments.length > 0 && <><h3 className="card-title">Repayment history</h3><div className="table-scroll"><table className="data-table"><thead><tr><th>Date</th><th>Lender</th><th>Principal</th><th>Interest expense</th><th>Total paid</th><th>Account</th><th>Status</th><th>Action</th></tr></thead><tbody>{records.loanRepayments.map(row => <tr key={row._id}><td>{formatBusinessDay(row.paidOn, dateFormat)}</td><td>{row.lender}</td><td>{fmt(row.principalUgx)}</td><td>{fmt(row.interestUgx)}</td><td>{fmt(row.amountUgx)}</td><td>{accountName(row.account)}</td><td>{row.state === "void" ? `Reversed · ${row.voidReason ?? ""}` : "Posted"}</td><td>{records.role === "owner" && row.state === "posted" ? <button className="button" type="button" disabled={busy} onClick={() => { const reason = window.prompt("Reason for reversing this repayment (at least 5 characters):") ?? ""; if (reason.trim().length >= 5) void reverseWithReview(confirmed => reverseLoanRepayment({ businessId: selectedBusinessId(), repaymentId: row._id, reason, confirmNegativeBalance: confirmed }), "Loan repayment reversed; principal and linked expense history were updated."); }}>Reverse…</button> : "—"}</td></tr>)}</tbody></table></div></>}{rowActions}</Card>
  </div>;

  if (screen === "Bills") return <div className="board-grid board-grid-operations">{periodNote}{sharedMessages}
    <div id="record-entry-card" hidden={!recordFormOpen}><Card className="board-feature-card">
      {canCreateBills && <><h2 className="card-title">Set up a recurring bill</h2><p className="card-subtitle">The due countdown refreshes automatically. Recording a payment creates the expense and advances the next due date by this schedule.</p><form className="form-layout" onSubmit={form("bill", async (v, key) => createBill({ businessId: selectedBusinessId(), name: String(v.get("name")), category: String(v.get("category")) === "Other" ? String(v.get("otherCategory") ?? "").trim() : String(v.get("category")), amountUgx: Math.round(Number(v.get("amount")) * scale), account: String(v.get("account")) as Account, recurrence: String(v.get("recurrence")) as "weekly" | "monthly" | "quarterly" | "yearly", nextDueOn: String(v.get("nextDueOn")), idempotencyKey: key }))}><div className="field"><label htmlFor="bill-name">Bill name</label><input id="bill-name" name="name" minLength={2} maxLength={100} required /></div><div className="field"><label htmlFor="bill-category">Expense category</label><select id="bill-category" name="category" value={billCategory} onChange={event => setBillCategory(event.target.value)}><option>Bandwidth</option><option>Electricity</option><option>Hardware</option><option>Utilities</option><option>Rent</option><option>Transport &amp; airtime</option><option>Other</option></select></div>{billCategory === "Other" && <div className="field"><label htmlFor="bill-other-category">Bill category</label><input id="bill-other-category" name="otherCategory" maxLength={80} minLength={2} placeholder="Enter the bill category" required /></div>}<div className="field"><label htmlFor="bill-amount">Expected amount ({currency})</label><input id="bill-amount" name="amount" type="number" min={1 / scale} step={1 / scale} required /></div><div className="field"><label htmlFor="bill-account">Usually paid from</label><select id="bill-account" name="account"><option value="cash">Cash</option><option value="mobile_money">Mobile money</option></select></div><div className="field"><label htmlFor="bill-recurrence">Recurrence</label><select id="bill-recurrence" name="recurrence"><option value="monthly">Monthly</option><option value="weekly">Weekly</option><option value="quarterly">Quarterly</option><option value="yearly">Yearly</option></select></div><div className="field"><label htmlFor="bill-next">Next due</label><input id="bill-next" name="nextDueOn" type="date" defaultValue={day} required /></div><div className="form-actions"><button className="button button-accent" disabled={busy}>Save bill schedule</button></div></form></>}
      {canPayBills && records.bills.length > 0 && <><h3 className="card-title">Confirm a payment</h3><form className="form-layout" onSubmit={form("bill-payment", async (v, key, confirmNegative) => recordBillPayment({ businessId: selectedBusinessId(), billId: String(v.get("billId")) as Id<"bills">, paidOn: String(v.get("paidOn")), amountUgx: v.get("amount") ? Math.round(Number(v.get("amount")) * scale) : undefined, account: String(v.get("account")) as Account, idempotencyKey: key, confirmNegativeBalance: confirmNegative }))}><div className="field"><label htmlFor="payment-bill">Bill</label><select id="payment-bill" name="billId">{records.bills.map(row => <option key={row._id} value={row._id}>{row.name} · {billDueLabel(row.nextDueOn)} · {fmt(row.amountUgx)}</option>)}</select></div><div className="field"><label htmlFor="payment-account">Actually paid from</label><select id="payment-account" name="account" required defaultValue=""><option value="" disabled>Choose the account used</option><option value="cash">Cash</option><option value="mobile_money">Mobile money</option></select></div><div className="field"><label htmlFor="payment-date">Payment date</label><input id="payment-date" name="paidOn" type="date" defaultValue={day} required /></div><div className="field"><label htmlFor="payment-amount">Actual amount ({currency}, optional)</label><input id="payment-amount" name="amount" type="number" min={1 / scale} step={1 / scale} /></div><div className="form-actions"><button className="button button-accent" disabled={busy}>Confirm payment and record expense</button></div></form></>}
    </Card></div>
    <Card className="board-section-card"><h2 className="card-title">Bills and next due dates</h2>{records.bills.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>Bill</th><th>Category</th><th>Expected</th><th>Recurrence</th><th>Next due</th><th>Next payment</th><th>Actions</th></tr></thead><tbody>{records.bills.map(row => <tr key={row._id}><td>{row.name}</td><td>{row.category}</td><td>{fmt(row.amountUgx)}</td><td>{row.recurrence}</td><td>{formatBusinessDay(row.nextDueOn, dateFormat)}<div className={`bill-due-state${row.nextDueOn < day ? " is-overdue" : ""}`}><span className={`status-chip ${row.nextDueOn <= day ? "status-warning" : "status-ok"}`}>{billDueLabel(row.nextDueOn)}</span></div></td><td>{fmt(row.amountUgx)}<div className="muted-note">Expected amount</div></td><td>{records.role === "owner" ? <><button className="button" type="button" disabled={busy} onClick={() => { const name = window.prompt("Bill name:", row.name); if (name === null) return; const category = window.prompt("Expense category:", row.category); if (category === null) return; const amount = window.prompt(`Expected amount in ${currency}:`, String(row.amountUgx / scale)); if (amount === null) return; const nextDueOn = window.prompt("Next due date (YYYY-MM-DD):", row.nextDueOn); if (nextDueOn === null) return; void saveLifecycleChange(() => updateBillSchedule({ businessId: selectedBusinessId(), billId: row._id, action: "edit", expectedActive: true, expectedNextDueOn: row.nextDueOn, name, category, amountUgx: Math.round(Number(amount) * scale), account: row.account, recurrence: row.recurrence, nextDueOn }), "Bill schedule updated."); }}>Edit</button> <button className="button" type="button" disabled={busy} onClick={() => { if (window.confirm(`Archive ${row.name}? Payment history will remain available.`)) void saveLifecycleChange(() => updateBillSchedule({ businessId: selectedBusinessId(), billId: row._id, action: "archive", expectedActive: true, expectedNextDueOn: row.nextDueOn, name: row.name, category: row.category, amountUgx: row.amountUgx, account: row.account, recurrence: row.recurrence, nextDueOn: row.nextDueOn }), "Bill schedule archived."); }}>Archive</button></> : "—"}</td></tr>)}</tbody></table></div> : <Empty message="No recurring bills configured." detail={recordFormOpen ? "Save the schedule above to add your first bill. A schedule does not book accruals or expenses automatically." : "Use Record in the page action bar to add a bill schedule. A schedule does not book accruals or expenses automatically."} />}{billArchive.results.length > 0 && <details className="record-archive"><summary>Archived bill schedules ({billArchive.results.length})</summary><div className="table-scroll"><table className="data-table"><thead><tr><th>Bill</th><th>Category</th><th>Expected</th><th>Action</th></tr></thead><tbody>{billArchive.results.map(row => <tr key={row._id}><td>{row.name}</td><td>{row.category}</td><td>{fmt(row.amountUgx)}</td><td>{records.role === "owner" ? <button className="button" type="button" disabled={busy} onClick={() => void saveLifecycleChange(() => updateBillSchedule({ businessId: selectedBusinessId(), billId: row._id, action: "restore", expectedActive: false, expectedNextDueOn: row.nextDueOn, name: row.name, category: row.category, amountUgx: row.amountUgx, account: row.account, recurrence: row.recurrence, nextDueOn: row.nextDueOn }), "Bill schedule restored.")}>Restore</button> : "—"}</td></tr>)}</tbody></table>{billArchive.status === "CanLoadMore" && <button className="button" type="button" onClick={() => billArchive.loadMore(20)}>Load older archived schedules</button>}</div></details>}{records.billPayments.length > 0 && <><h3 className="card-title">Payment history</h3><div className="table-scroll"><table className="data-table"><thead><tr><th>Paid on</th><th>Bill</th><th>Expense amount</th><th>Paid from</th><th>Status</th><th>Action</th></tr></thead><tbody>{records.billPayments.map(row => <tr key={row._id}><td>{formatBusinessDay(row.paidOn, dateFormat)}</td><td>{row.billName}</td><td>{fmt(row.amountUgx)}</td><td>{row.account ? accountName(row.account) : "Not recorded on this older payment"}</td><td>{row.state === "void" ? `Reversed · ${row.voidReason ?? ""}` : row.canReverse ? "Posted" : "Posted · schedule changed; review"}</td><td>{records.role === "owner" && row.state === "posted" && row.canReverse ? <button className="button" type="button" disabled={busy} onClick={() => { const reason = window.prompt("Reason for reversing this bill payment (at least 5 characters):") ?? ""; if (reason.trim().length >= 5) void reverseWithReview(() => reverseBillPayment({ businessId: selectedBusinessId(), paymentId: row._id, reason }), "Bill payment reversed; account, expense, and due-date history were restored."); }}>Reverse…</button> : "—"}</td></tr>)}</tbody></table></div></>}{rowActions}</Card>
  </div>;

  if (screen === "Reconcile") return <div className="board-grid board-grid-operations">{periodNote}{sharedMessages}
    <div id="record-entry-card" hidden={!recordFormOpen}><Card className="board-feature-card"><h2 className="card-title">Record an account count</h2><p className="card-subtitle">This captures the book balance and counted balance at that moment. It never edits cashbook transactions.</p><form className="form-layout" onSubmit={form("reconcile", async (v, key) => createReconciliation({ businessId: selectedBusinessId(), account: String(v.get("account")) as Account, asOfDate: String(v.get("asOfDate")), countedBalanceUgx: Math.round(Number(v.get("counted")) * scale), note: String(v.get("note") ?? ""), idempotencyKey: key }))}><div className="field"><label htmlFor="count-account">Account</label><select id="count-account" name="account"><option value="cash">Cash</option><option value="mobile_money">Mobile money</option></select></div><div className="field"><label htmlFor="count-date">Count date</label><input id="count-date" name="asOfDate" type="date" defaultValue={day} required /></div><div className="field"><label htmlFor="count-amount">Counted balance ({currency})</label><input id="count-amount" name="counted" type="number" min="0" step={1 / scale} required /></div><div className="field"><label htmlFor="count-note">Count notes</label><input id="count-note" name="note" maxLength={300} /></div><div className="form-actions"><button className="button button-accent" disabled={busy}>Save count</button></div></form></Card></div>
    <Card className="board-section-card"><h2 className="card-title">Recent reconciliations</h2>{records.reconciliations.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>Date</th><th>Account</th><th>Book</th><th>Counted</th><th>Variance</th><th>Status</th><th>Correction</th></tr></thead><tbody>{records.reconciliations.map(row => <tr key={row._id}><td>{formatBusinessDay(row.asOfDate, dateFormat)}</td><td>{accountName(row.account)}</td><td>{fmt(row.bookBalanceUgx)}</td><td>{fmt(row.countedBalanceUgx)}</td><td>{fmt(row.varianceUgx)}</td><td>{row.status === "open" && records.role === "owner" ? <form onSubmit={form(`explain-${row._id}`, async v => explainReconciliation({ businessId: selectedBusinessId(), reconciliationId: row._id, explanation: String(v.get("explanation")) }))}><input aria-label="Explain reconciliation difference" name="explanation" minLength={5} maxLength={300} placeholder="Explain variance" required /><button className="button" disabled={busy}>Mark explained</button></form> : row.status === "explained" && records.role === "owner" ? <><span title={row.explanation}>Explained</span> <button className="button" type="button" disabled={busy} onClick={() => { const reason = window.prompt("Reason for reopening this difference (at least 5 characters):") ?? ""; if (reason.trim().length >= 5) void saveLifecycleChange(() => reopenReconciliation({ businessId: selectedBusinessId(), reconciliationId: row._id, reason }), "Reconciliation reopened with an audit reason."); }}>Reopen…</button></> : row.status === "superseded" ? "Superseded by corrected count" : row.status}</td><td>{records.role === "owner" && row.status !== "superseded" && row.asOfDate === day ? <button className="button" type="button" disabled={busy} onClick={() => { const rawCount = window.prompt(`Corrected counted balance in ${currency}:`, String(row.countedBalanceUgx / scale)); if (rawCount === null) return; const scaledCount = Number(rawCount) * scale; const countedBalanceUgx = Math.round(scaledCount); if (!Number.isFinite(scaledCount) || Math.abs(scaledCount - countedBalanceUgx) > 1e-8 || countedBalanceUgx < 0 || !Number.isSafeInteger(countedBalanceUgx)) { window.alert("Enter a valid balance using the currency's supported decimal places."); return; } const note = window.prompt("Reason for correcting this count (at least 5 characters):") ?? ""; if (note.trim().length < 5) return; void saveLifecycleChange(() => supersedeReconciliation({ businessId: selectedBusinessId(), reconciliationId: row._id, countedBalanceUgx, note, idempotencyKey: crypto.randomUUID() }), "Reconciliation corrected. The original count remains in history."); }}>Correct…</button> : row.supersedesId ? "Correction of earlier count" : "—"}</td></tr>)}</tbody></table></div> : <Empty message="No reconciliation counts recorded." detail="Use Record in the page action bar to enter a physical cash count or verified mobile-money balance." />}{rowActions}</Card>
  </div>;

  return <div className="board-grid board-grid-operations">{periodNote}{sharedMessages}
    {records.role === "owner" && <div id="record-entry-card" hidden={!recordFormOpen}><Card className="board-feature-card"><h2 className="card-title">Add a business partner</h2><p className="card-subtitle">Add partner records with total ownership at or below 100%. Distributions require exactly 100% ownership.</p><form className="form-layout" onSubmit={form("partner", async (v, key) => createPartner({ businessId: selectedBusinessId(), name: String(v.get("name")), ownershipBps: Math.round(Number(v.get("ownership")) * 100), idempotencyKey: key }))}><div className="field"><label htmlFor="partner-name">Partner name</label><input id="partner-name" name="name" minLength={2} maxLength={100} required /></div><div className="field"><label htmlFor="partner-share">Ownership (%)</label><input id="partner-share" name="ownership" type="number" min="0" max="100" step="0.01" required /></div><div className="form-actions"><button className="button button-accent" disabled={busy}>Save partner</button></div></form></Card></div>}
    <Card className="board-section-card"><h2 className="card-title">Active ownership</h2>{records.partners.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>Partner</th><th>Ownership</th><th>Status</th><th>Actions</th></tr></thead><tbody>{records.partners.map(row => <tr key={row._id}><td>{row.name}</td><td>{(row.ownershipBps / 100).toFixed(2)}%</td><td>{row.active ? "Active" : "Inactive"}</td><td>{records.role === "owner" ? <><button className="button" type="button" disabled={busy} onClick={() => { const name = window.prompt("Partner name:", row.name); if (name !== null) void saveLifecycleChange(() => updatePartnerProfile({ businessId: selectedBusinessId(), partnerId: row._id, name }), "Partner profile updated."); }}>Edit name</button> <button className="button" type="button" disabled={busy} onClick={() => { if (window.confirm(`Archive ${row.name}? First set their effective ownership to 0% and remove active access links.`)) void saveLifecycleChange(() => updatePartnerStatus({ businessId: selectedBusinessId(), partnerId: row._id, active: false }), "Partner archived. Historical ownership and distributions remain available."); }}>Archive</button></> : "—"}</td></tr>)}</tbody></table></div> : <Empty message="No partners configured." detail="Use Record in the page action bar to add a partner. Statement access remains restricted until partner identities are linked." />}{partnerArchive.results.length > 0 && <details className="record-archive"><summary>Archived partners ({partnerArchive.results.length})</summary><div className="table-scroll"><table className="data-table"><thead><tr><th>Partner</th><th>Current share</th><th>Action</th></tr></thead><tbody>{partnerArchive.results.map(row => <tr key={row._id}><td>{row.name}</td><td>{(row.ownershipBps / 100).toFixed(2)}%</td><td>{records.role === "owner" ? <button className="button" type="button" disabled={busy} onClick={() => void saveLifecycleChange(() => updatePartnerStatus({ businessId: selectedBusinessId(), partnerId: row._id, active: true }), "Partner restored with its saved ownership history.")}>Restore</button> : "—"}</td></tr>)}</tbody></table>{partnerArchive.status === "CanLoadMore" && <button className="button" type="button" onClick={() => partnerArchive.loadMore(20)}>Load older archived partners</button>}</div></details>}{rowActions}</Card>
    {records.role === "owner" && <PartnerDistributions range={range} currency={currency} scale={scale} locale={locale} dateFormat={dateFormat} partners={records.partners} today={today} />}
  </div>;
}

function Empty({ message, detail }: { message: string; detail: string }) {
  return <div className="empty-state compact-empty"><strong>{message}</strong><span>{detail}</span></div>;
}
